cd /tmp/exp && python3 - <<'EOF'
import json,collections
def load(t): return [json.loads(l) for l in open(t+'.ndjson')]
R={t:load(t) for t in ['Patient','EpisodeOfCare','Condition','Observation','Specimen','Basic','MedicationAdministration','MedicationDispense','DocumentReference','Task','AllergyIntolerance']}
pat={p['id']:p for p in R['Patient']}
# specimen label vs patient
mis=0
for s in R['Specimen']:
    pid=s['subject']['reference'].split('/')[1]
    ext={e['url'].split('/')[-1]:e.get('valueString') or e.get('valueDate') or e.get('valueDateTime') for e in s['extension']}
    p=pat[pid]
    if ext['label-mrn']!=p['identifier'][0]['value'] or ext['label-dob']!=p['birthDate']:
        mis+=1
print('specimen label mismatch (mrn/dob) count',mis)
# accession entries
acc={}
for b in R['Basic']:
    ext={e['url'].split('/')[-1]:(e.get('valueString') or e.get('valueDate') or e.get('valueDateTime')) for e in b['extension']}
    acc.setdefault(ext['accession'],[]).append((b['id'],ext))
print('accessions',len(acc), 'dups',sum(1 for k,v in acc.items() if len(v)>1))
# obs w/o specimen / specimen w/o obs
obsbyspec=collections.Counter(o['specimen']['reference'].split('/')[1] for o in R['Observation'] if 'specimen' in o)
print('obs count',len(R['Observation']),'obs with spec',sum(obsbyspec.values()))
specids={s['id'] for s in R['Specimen']}
print('specimens no obs',len(specids-set(obsbyspec)))
EOF

